                <option value="Média">Média</option>
                <option value="Alta">Alta</option>
            </select>
        </div>
        <div class="form-group">
            <label for="version">Versão do ChatGPT:</label>
            <select id="version" class="form-control">
                <option value="3.5">3.5</option>
                <option value="4.0">4.0</option>
                <!-- Adicione mais versões conforme necessário -->
            </select>
        </div>
        <div class="form-group">
            <label for="prompt">Prompt:</label>
            <textarea id="prompt" class="form-control" rows="3" placeholder="Insira seu prompt aqui"></textarea>
        </div>
        <button class="btn btn-primary btn-block">Gerar Código</button>
        <h2 class="mt-4">Código Gerado:</h2>
        <pre id="code-output" class="bg-light p-3 border"></pre>
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', function() {
            const apiKeyInput = document.getElementById('api_key');
            const languageSelect = document.getElementById('language');
            const complexitySelect = document.getElementById('complexity');
            const versionSelect = document.getElementById('version');
            const promptInput = document.getElementById('prompt');
            const generateButton = document.querySelector('.btn.btn-primary.btn-block');
            const codeOutput = document.getElementById('code-output');

            generateButton.addEventListener('click', generateProgram);

            function generateProgram() {
                const apiKey = apiKeyInput.value;
                const language = languageSelect.value;
                const complexity = complexitySelect.value;
                const version = versionSelect.value;
                const prompt = promptInput.value;

                if (!apiKey || !prompt) {
                    alert('Por favor, insira sua chave de API e prompt.');
                    return;
                }

                // Simulação de chamada de API para gerar código
                setTimeout(() => {
                    const generatedCode = `Aqui está o código gerado para:\nLinguagem: ${language}\nComplexidade: ${complexity}\nVersão do ChatGPT: ${version}\nPrompt: ${prompt}\n\n// Seu código gerado estará aqui!`;
                    codeOutput.textContent = generatedCode;
                }, 1000);
            }
        });
    </script>
</body>
</html>
```

### Explicação do Código:
- **HTML Estrutural**: O código HTML cria um formulário com campos para a chave da API, linguagem, complexidade, versão do ChatGPT e um prompt. Um botão é fornecido para gerar o código.
- **JavaScript**: O script é adicionado no final do corpo do documento. Ele escuta o evento de clique no botão e gera um código simulado com base nas entradas do usuário.
- **Estilo**: O Bootstrap é utilizado para estilizar o formulário e os botões, tornando a interface mais amigável.

Você pode copiar e colar esse código em um arquivo `.html` e abri-lo em um navegador para ver como funciona.

