            .get()
            .addOnSuccessListener { documents ->
                val dataList = documents.map { doc ->
                    DataModel(
                        id = doc.id,
                        value = doc.getLong("value")?.toInt() ?: 0,
                        timestamp = doc.getLong("timestamp") ?: 0L
                    )
                }
                callback(dataList)
            }
            .addOnFailureListener { exception ->
                // Handle the error
            }
    }

    fun fetchMonthlyData(callback: (List<DataModel>) -> Unit) {
        val startOfMonth = System.currentTimeMillis() - (30 * 24 * 60 * 60 * 1000) // 30 days ago
        firestore.collection("your_collection")
            .whereGreaterThan("timestamp", startOfMonth)
            .get()
            .addOnSuccessListener { documents ->
                val dataList = documents.map { doc ->
                    DataModel(
                        id = doc.id,
                        value = doc.getLong("value")?.toInt() ?: 0,
                        timestamp = doc.getLong("timestamp") ?: 0L
                    )
                }
                callback(dataList)
            }
            .addOnFailureListener { exception ->
                // Handle the error
            }
    }

    fun fetchYearlyData(callback: (List<DataModel>) -> Unit) {
        val startOfYear = System.currentTimeMillis() - (365 * 24 * 60 * 60 * 1000) // 365 days ago
        firestore.collection("your_collection")
            .whereGreaterThan("timestamp", startOfYear)
            .get()
            .addOnSuccessListener { documents ->
                val dataList = documents.map { doc ->
                    DataModel(
                        id = doc.id,
                        value = doc.getLong("value")?.toInt() ?: 0,
                        timestamp = doc.getLong("timestamp") ?: 0L
                    )
                }
                callback(dataList)
            }
            .addOnFailureListener { exception ->
                // Handle the error
            }
    }
}
```

### Step 4: Create a ViewModel

Create a ViewModel that will interact with the repository and provide data to the UI.

```kotlin
class DataViewModel : ViewModel() {

    private val repository = DataRepository()
    private val _weeklyData = MutableLiveData<List<DataModel>>()
    val weeklyData: LiveData<List<DataModel>> get() = _weeklyData

    private val _monthlyData = MutableLiveData<List<DataModel>>()
    val monthlyData: LiveData<List<DataModel>> get() = _monthlyData

    private val _yearlyData = MutableLiveData<List<DataModel>>()
    val yearlyData: LiveData<List<DataModel>> get() = _yearlyData

    fun fetchWeeklyData() {
        repository.fetchWeeklyData { data ->
            _weeklyData.postValue(data)
        }
    }

    fun fetchMonthlyData() {
        repository.fetchMonthlyData { data ->
            _monthlyData.postValue(data)
        }
    }

    fun fetchYearlyData() {
        repository.fetchYearlyData { data ->
            _yearlyData.postValue(data)
        }
    }
}
```

### Step 5: Use ViewModel in Your Activity/Fragment

In your Activity or Fragment, observe the LiveData from the ViewModel and update the UI accordingly.

```kotlin
class YourActivity : AppCompatActivity() {

    private lateinit var viewModel: DataViewModel

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_your)

        viewModel = ViewModelProvider(this).get(DataViewModel::class.java)

        viewModel.weeklyData.observe(this, { data ->
            // Update your UI with weekly data
        })

        viewModel.monthlyData.observe(this, { data ->
            // Update your UI with monthly data
        })

        viewModel.yearlyData.observe(this, { data ->
            // Update your UI with yearly data
        })

        // Fetch data
        viewModel.fetchWeeklyData()
        viewModel.fetchMonthlyData()
        viewModel.fetchYearlyData()
    }
}
```

### Conclusion

This is a basic implementation of fetching data from Firestore using a clean architecture approach with ViewModel. You can expand upon this by adding error handling, loading states, and more complex data processing as needed. Make sure to replace `"your_collection"` with the actual name of your Firestore collection.

